COMMIT;

-- Resumen
SELECT 'depositos' AS tabla, COUNT(*)::text AS n FROM depositos
UNION ALL SELECT 'sectores', COUNT(*)::text FROM sectores
UNION ALL SELECT 'ubicaciones', COUNT(*)::text FROM ubicaciones
UNION ALL SELECT 'categorias', COUNT(*)::text FROM categorias
UNION ALL SELECT 'activos', COUNT(*)::text FROM activos
UNION ALL SELECT 'activos_sin_ubicacion', COUNT(*)::text FROM activos WHERE ubicacion_id IS NULL
UNION ALL SELECT 'inventarios', COUNT(*)::text FROM inventarios
UNION ALL SELECT 'transferencias', COUNT(*)::text FROM transferencias
UNION ALL SELECT 'historial', COUNT(*)::text FROM historial_activos
ORDER BY 1;
